function fixture(t){const root=fs.mkdtempSync(path.join(os.tmpdir(),'ltds-v16-'));for(const name of['datasets','models','cache','trash','imports'])fs.mkdirSync(path.join(root,name));const db=openDatabase(path.join(root,'viewer.sqlite')),processing=new ProcessingRepository(db),repository=new ViewerRepository(db),storage=new StorageManager({datasetsMount:path.join(root,'datasets'),modelsMount:path.join(root,'models'),cacheMount:path.join(root,'cache'),trashMount:path.join(root,'trash'),datasetImportMount:path.join(root,'imports'),storageReserveBytes:0,storageReservePercent:0});storage.initialize();t.after(()=>{db.close();fs.rmSync(root,{recursive:true,force:true});});return{root,db,processing,repository,storage};}
function dataset(c,project,specs){const relativePath=crypto.randomUUID(),draft=c.processing.createDataset({projectId:project.id,displayName:`Dataset ${relativePath.slice(0,6)}`,storageMode:'managed',rootKey:'datasets',relativePath}),directory=path.join(c.root,'datasets',relativePath);fs.mkdirSync(directory,{recursive:true});const files=specs.map((spec)=>{const body=Buffer.from(spec.body||spec.name);fs.writeFileSync(path.join(directory,spec.name),body);return{relativePath:spec.name,byteSize:body.length,sha256:crypto.createHash('sha256').update(body).digest('hex'),...(spec.processingRole?{processingRole:spec.processingRole}:{})};});c.processing.finalizeDataset(draft.id,files,crypto.createHash('sha256').update(JSON.stringify(files)).digest('hex'));return c.processing.getDataset(draft.id,true);}
function reviewable(c){const project=c.processing.createProject({displayName:`Project ${crypto.randomUUID()}`}),data=dataset(c,project,[{name:'photo.jpg'}]),task=c.processing.createTask({projectId:project.id,datasetId:data.id,displayName:'Task'}),provider=c.processing.upsertProvider({type:'nodeodm',displayName:'ODM',endpoint:'http://127.0.0.1:3000',enabled:true}),attempt=c.processing.createAttempt({taskId:task.id,providerId:provider.id,options:{},createdBy:'ops:test'}),model=c.repository.upsertModelVersion({provider:'ltds-processing',providerModelId:task.id,providerVersionId:attempt.id,displayName:task.displayName,status:'ready',assets:[{kind:'glb',rootKey:'models',relativePath:`${task.id}/${attempt.id}/model.glb`,sha256:'a'.repeat(64),published:false}],makeActive:false}),versionId=c.db.prepare('SELECT id FROM model_versions WHERE model_id=?').get(model.id).id;c.processing.setAttemptResult(attempt.id,model.id,versionId);c.processing.transitionAttempt(attempt.id,'ready_for_review',{progress:1});c.processing.registerModelOutput({versionId,modelId:model.id,taskId:task.id,attemptId:attempt.id,projectId:project.id,relativePath:`${task.id}/${attempt.id}`,byteSize:1,assetCount:1});return{project,data,task,attempt,model,versionId};}
function stagedImported(c,label='Imported'){const project=c.processing.createProject({displayName:`${label} project`}),data=dataset(c,project,[{name:'model.glb'}]),task=c.processing.createTask({projectId:project.id,datasetId:data.id,displayName:`${label} task`}),attempt=c.processing.createImportedAttempt({id:crypto.randomUUID(),taskId:task.id,datasetId:data.id,providerTaskId:`import:${label}`,createdBy:'ops:test'}),model=c.repository.upsertModelVersion({provider:'webodm',providerModelId:`import:${attempt.id}`,providerVersionId:attempt.id,displayName:task.displayName,status:'importing',assets:[{kind:'glb',rootKey:'datasets',relativePath:`${data.relativePath}/model.glb`,sha256:'a'.repeat(64),published:false}],makeActive:false}),versionId=c.db.prepare('SELECT id FROM model_versions WHERE model_id=?').get(model.id).id;c.processing.setAttemptResult(attempt.id,model.id,versionId);c.processing.registerModelOutput({versionId,modelId:model.id,taskId:task.id,attemptId:attempt.id,projectId:project.id,rootKey:'datasets',relativePath:data.relativePath,status:'staged',byteSize:1,assetCount:1});return{project,data,task,attempt:c.processing.getAttempt(attempt.id),model,versionId};}

test('auto administrative files stay private while explicit provider inputs upload',async(t)=>{const c=fixture(t),project=c.processing.createProject({displayName:'Roles'}),data=dataset(c,project,[{name:'photo.jpg'},{name:'private.json'},{name:'control.json',processingRole:'provider_input'},{name:'points.csv'}]);assert.deepEqual(Object.fromEntries(data.files.map((f)=>[f.relativePath,f.processingRole])),{'control.json':'provider_input','photo.jpg':'image','points.csv':'gcp_source','private.json':'administrative'});const task=c.processing.createTask({projectId:project.id,datasetId:data.id,displayName:'Roles task'}),provider=c.processing.upsertProvider({type:'nodeodm',displayName:'ODM',endpoint:'http://127.0.0.1:3000',enabled:true}),attempt=c.processing.createAttempt({taskId:task.id,providerId:provider.id,options:{}}),job=c.processing.claimJob('roles-worker'),uploaded=[];c.storage.requireProcessingHeadroom=()=>({});await processSubmit(job,{processing:c.processing,storage:c.storage,config:{},signal:new AbortController().signal,adapterFactory:()=>({status:async()=>{throw Object.assign(new Error('missing'),{code:'provider_task_not_found'});},initialize:async()=>{},upload:async(_id,batch)=>uploaded.push(...batch.map((file)=>file.relativePath)),commit:async()=>{}})});assert.deepEqual(uploaded.sort(),['control.json','photo.jpg']);});

test('publication and readiness roll back when their atomic audit insert fails',(t)=>{const c=fixture(t),ready=reviewable(c);c.db.exec("CREATE TRIGGER reject_publish_audit BEFORE INSERT ON audit_events WHEN NEW.action='processing_attempt.published' BEGIN SELECT RAISE(ABORT,'injected publish audit failure'); END");assert.throws(()=>c.processing.publishAttemptAtomic(ready.attempt.id,['glb'],{actorId:'ops:test'}),/injected publish/);assert.equal(c.processing.getAttempt(ready.attempt.id).status,'ready_for_review');assert.equal(c.processing.getTask(ready.task.id).publishedModelId,null);assert.equal(c.processing.getModelOutput(ready.versionId).status,'ready');assert.equal(c.db.prepare('SELECT active_version_id FROM models WHERE id=?').get(ready.model.id).active_version_id,null);assert.equal(c.db.prepare('SELECT published FROM model_assets WHERE version_id=?').get(ready.versionId).published,0);c.db.exec('DROP TRIGGER reject_publish_audit');assert.ok(c.processing.publishAttemptAtomic(ready.attempt.id,['glb'],{actorId:'ops:test'}));assert.equal(c.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='processing_attempt.published' AND entity_id=?").get(ready.attempt.id).n,1);
  const second=reviewable(c);c.processing.transitionAttempt(second.attempt.id,'derivatives');c.db.prepare("UPDATE model_outputs SET status='staged' WHERE id=?").run(second.versionId);c.db.prepare("UPDATE model_versions SET status='importing' WHERE id=?").run(second.versionId);c.db.exec("CREATE TRIGGER reject_ready_audit BEFORE INSERT ON audit_events WHEN NEW.action='processing_attempt.ready_for_review' BEGIN SELECT RAISE(ABORT,'injected ready audit failure'); END");assert.throws(()=>c.processing.completeOutputForReview(second.attempt.id,{event:{eventId:`processing-ready-${second.attempt.id}`}}),/injected ready/);assert.equal(c.processing.getAttempt(second.attempt.id).status,'derivatives');assert.equal(c.processing.getModelOutput(second.versionId).status,'staged');assert.equal(c.db.prepare('SELECT status FROM model_versions WHERE id=?').get(second.versionId).status,'importing');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(`processing-ready-${second.attempt.id}`).n,0);});

test('transaction preserves the triggering error after SQLite has already rolled back',(t)=>{const c=fixture(t),original=Object.assign(new Error('original transaction failure'),{code:'original_failure'});assert.throws(()=>c.processing.transaction(()=>{c.db.exec('ROLLBACK');throw original;}),(error)=>error===original);assert.equal(c.db.isTransaction,false);});

test('model output registration and base storage accounting share one transaction',(t)=>{
  const c=fixture(t),project=c.processing.createProject({displayName:'Atomic base project'}),data=dataset(c,project,[{name:'model.glb'}]),task=c.processing.createTask({projectId:project.id,datasetId:data.id,displayName:'Atomic base task'}),attempt=c.processing.createImportedAttempt({id:crypto.randomUUID(),taskId:task.id,datasetId:data.id,providerTaskId:'import:atomic-base',createdBy:'ops:test'}),model=c.repository.upsertModelVersion({provider:'webodm',providerModelId:`import:${attempt.id}`,providerVersionId:attempt.id,displayName:task.displayName,status:'importing',assets:[],makeActive:false}),versionId=c.db.prepare('SELECT id FROM model_versions WHERE model_id=?').get(model.id).id;c.processing.setAttemptResult(attempt.id,model.id,versionId);const input={versionId,modelId:model.id,taskId:task.id,attemptId:attempt.id,projectId:project.id,rootKey:'datasets',relativePath:data.relativePath,status:'staged',byteSize:123,assetCount:0};
  c.db.exec("CREATE TRIGGER reject_base_component BEFORE INSERT ON model_output_storage_components BEGIN SELECT RAISE(ABORT,'injected base component failure'); END");assert.throws(()=>c.processing.registerModelOutput(input),/injected base component/);assert.equal(c.processing.getModelOutput(versionId),null);c.db.exec('DROP TRIGGER reject_base_component');assert.ok(c.processing.registerModelOutput(input));const component=c.db.prepare("SELECT component_key,root_key,relative_path,byte_size FROM model_output_storage_components WHERE output_id=?").get(versionId);assert.equal(component.component_key,'base');assert.equal(component.root_key,'datasets');assert.equal(component.relative_path,data.relativePath);assert.equal(component.byte_size,123);
});

test('required import derivative activation and operation linkage share one visibility boundary',(t)=>{
  const c=fixture(t),item=stagedImported(c,'Atomic required'),owner='import-worker',operationId=crypto.randomUUID(),created=new Date().toISOString(),expires=new Date(Date.now()+60_000).toISOString(),specs=[{type:'ept',request:{optional:false}},{type:'mesh_tiles',request:{optional:false}}],result={task:item.task,attempt:item.attempt,model:c.repository.getModelVersion(item.model.id,item.versionId),requiredDerivatives:specs};
  c.db.prepare("INSERT INTO dataset_operations(id,operation_type,subject,payload_json,status,lease_owner,lease_expires_at,available_at,created_at,updated_at) VALUES (?,'catalog_map','ops:test','{}','leased',?,?,?,?,?)").run(operationId,owner,expires,created,created,created);
  c.db.exec("CREATE TRIGGER reject_operation_link BEFORE UPDATE OF status ON dataset_operations WHEN NEW.status='awaiting_derivatives' BEGIN SELECT RAISE(ABORT,'injected operation linkage failure'); END");
  assert.throws(()=>c.processing.activateImportedDerivativesForOperation(operationId,owner,item.attempt.id,specs,result),/injected operation linkage/);
  assert.equal(c.processing.getAttempt(item.attempt.id).status,'ingesting');assert.equal(c.processing.getModelOutput(item.versionId).status,'staged');assert.equal(c.db.prepare('SELECT status FROM model_versions WHERE id=?').get(item.versionId).status,'importing');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM derivative_jobs WHERE attempt_id=?').get(item.attempt.id).n,0);const rawOperation=c.db.prepare('SELECT status,lease_owner FROM dataset_operations WHERE id=?').get(operationId);assert.equal(rawOperation.status,'leased');assert.equal(rawOperation.lease_owner,owner);
  c.db.exec('DROP TRIGGER reject_operation_link');
  const activated=c.processing.activateImportedDerivativesForOperation(operationId,owner,item.attempt.id,specs,result);assert.equal(activated.status,'awaiting_derivatives');assert.equal(activated.processingAttemptId,item.attempt.id);assert.equal(c.processing.getAttempt(item.attempt.id).status,'derivatives');assert.equal(c.db.prepare("SELECT COUNT(*) n FROM derivative_jobs WHERE attempt_id=? AND status='pending'").get(item.attempt.id).n,2);const reservations=c.db.prepare('SELECT output_id,state,reserved_byte_size,accounted_byte_size FROM derivative_storage_journal ORDER BY job_id').all();assert.equal(reservations.length,2);for(const reservation of reservations){assert.equal(reservation.output_id,item.versionId);assert.equal(reservation.state,'reserved');assert.ok(reservation.reserved_byte_size>=8*1024**3);assert.equal(reservation.accounted_byte_size,reservation.reserved_byte_size);}const totalReservation=reservations.reduce((sum,row)=>sum+row.accounted_byte_size,0),firstJob=c.db.prepare('SELECT job_id,accounted_byte_size FROM derivative_storage_journal ORDER BY job_id LIMIT 1').get();assert.equal(c.processing.activeDerivativeReservationBytes(),totalReservation);assert.equal(c.processing.activeDerivativeReservationBytes(firstJob.job_id),totalReservation-firstJob.accounted_byte_size);assert.equal(activated.result.requiredDerivatives,undefined);
});

test('stale EPT lease cannot promote or register over its successor',(t)=>{
  const c=fixture(t),item=stagedImported(c,'EPT fence');c.processing.transitionAttempt(item.attempt.id,'derivatives');c.processing.addModelAsset({versionId:item.versionId,kind:'pointCloud',rootKey:'datasets',relativePath:`${item.data.relativePath}/cloud.laz`,format:'laz',byteSize:1,attemptId:item.attempt.id,sha256:'d'.repeat(64)});c.processing.enqueueDerivative(item.attempt.id,'ept',{optional:false});const stale=c.processing.claimDerivative('stale-ept');c.db.prepare("UPDATE derivative_jobs SET lease_expires_at='2000-01-01T00:00:00.000Z' WHERE id=?").run(stale.id);c.db.prepare("UPDATE lod_conversion_lock SET lease_expires_at='2000-01-01T00:00:00.000Z' WHERE job_id=?").run(stale.id);const successor=c.processing.claimDerivative('successor-ept'),files=[{relativePath:'ept.json',byteSize:2,sha256:'a'.repeat(64)},{relativePath:'ept-data/0.bin',byteSize:3,sha256:'b'.repeat(64)}],asset={versionId:item.versionId,rootKey:'models',relativePath:`${item.task.id}/${item.attempt.id}/ept-${stale.id}/ept.json`,format:'ept',contentType:'application/json',byteSize:2,attemptId:item.attempt.id,sha256:'a'.repeat(64),manifestSha256:'c'.repeat(64),manifestFiles:files};let stalePromoted=false,successorPromoted=false;assert.equal(c.processing.registerVerifiedEptAsset(stale.id,'stale-ept',asset,{leaseToken:stale.lease_token,promote:()=>{stalePromoted=true;}}),false);assert.equal(stalePromoted,false);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM model_assets WHERE version_id=? AND kind='ept'").get(item.versionId).n,0);assert.equal(c.processing.registerVerifiedEptAsset(successor.id,'successor-ept',asset,{leaseToken:successor.lease_token,promote:()=>{successorPromoted=true;}}),true);assert.equal(successorPromoted,true);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM model_assets WHERE version_id=? AND kind='ept'").get(item.versionId).n,1);let resumedPromotion=false;assert.equal(c.processing.registerVerifiedEptAsset(successor.id,'successor-ept',asset,{leaseToken:successor.lease_token,promote:()=>{resumedPromotion=true;}}),true);assert.equal(resumedPromotion,true);
});

test('required generated derivative completion settles its reservation and durable output bytes',(t)=>{
  const c=fixture(t),item=stagedImported(c,'Derivative accounting'),owner='import-owner',operationId=crypto.randomUUID(),created=new Date().toISOString(),expires=new Date(Date.now()+60_000).toISOString(),specs=[{type:'mesh_tiles',request:{optional:false}}],result={task:item.task,attempt:item.attempt,model:c.repository.getModelVersion(item.model.id,item.versionId),requiredDerivatives:specs};c.db.prepare("INSERT INTO dataset_operations(id,operation_type,subject,payload_json,status,lease_owner,lease_expires_at,available_at,created_at,updated_at) VALUES (?,'catalog_map','ops:test','{}','leased',?,?,?,?,?)").run(operationId,owner,expires,created,created,created);assert.equal(c.processing.activateImportedDerivativesForOperation(operationId,owner,item.attempt.id,specs,result).status,'awaiting_derivatives');const job=c.processing.claimDerivative('derivative-owner'),files=[{relativePath:'tileset.json',byteSize:7,sha256:'a'.repeat(64)},{relativePath:'LOD-0/leaf.b3dm',byteSize:11,sha256:'b'.repeat(64)}],base=c.db.prepare("SELECT byte_size FROM model_output_storage_components WHERE output_id=? AND component_key='base'").get(item.versionId).byte_size;c.processing.addModelAsset({versionId:item.versionId,kind:'tiles',rootKey:'models',relativePath:`${item.task.id}/${item.attempt.id}/tiles/tileset.json`,format:'3dtiles',contentType:'application/json',byteSize:7,attemptId:item.attempt.id,sha256:'a'.repeat(64),manifestSha256:'c'.repeat(64),manifestFiles:files});const completed=c.processing.completeDerivativeAndMaybeReady(job.id,'derivative-owner',{verified:true},{event:{eventId:`processing-ready-${item.attempt.id}`},leaseToken:job.lease_token});assert.equal(completed.ready,true);const journal=c.db.prepare('SELECT state,lease_token,actual_byte_size,accounted_byte_size,final_relative_path FROM derivative_storage_journal WHERE job_id=?').get(job.id);assert.equal(journal.state,'registered');assert.equal(journal.lease_token,job.lease_token);assert.equal(journal.actual_byte_size,18);assert.equal(journal.accounted_byte_size,18);assert.equal(journal.final_relative_path,`${item.task.id}/${item.attempt.id}/tiles`);const component=c.db.prepare('SELECT root_key,relative_path,byte_size,manifest_sha256 FROM model_output_storage_components WHERE output_id=? AND component_key=?').get(item.versionId,`derivative:${job.id}`);assert.equal(component.root_key,'models');assert.equal(component.relative_path,`${item.task.id}/${item.attempt.id}/tiles`);assert.equal(component.byte_size,18);assert.equal(component.manifest_sha256,'c'.repeat(64));assert.equal(c.processing.getModelOutput(item.versionId).byteSize,base+18);
});

test('an imported output with no required derivatives becomes ready exactly once',(t)=>{const c=fixture(t),item=stagedImported(c,'Atomic ready'),event={eventId:`processing-ready-${item.attempt.id}`};const ready=c.processing.completeOutputForReview(item.attempt.id,{event});assert.equal(ready.status,'ready_for_review');assert.ok(ready.ingestedAt);assert.equal(c.processing.getTask(item.task.id).status,'ready_for_review');assert.equal(c.processing.getModelOutput(item.versionId).status,'ready');assert.equal(c.db.prepare('SELECT status FROM model_versions WHERE id=?').get(item.versionId).status,'ready');const model=c.db.prepare('SELECT status,active_version_id FROM models WHERE id=?').get(item.model.id);assert.equal(model.status,'ready');assert.equal(model.active_version_id,null);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(event.eventId).n,1);assert.equal(c.processing.completeOutputForReview(item.attempt.id,{event}),null);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(event.eventId).n,1);});

test('required derivative failure preserves a previously published model while retrying the new version',(t)=>{
  const c=fixture(t),published=reviewable(c);
  assert.ok(c.processing.publishAttemptAtomic(published.attempt.id,['glb'],{actorId:'ops:test'}));
  const attempt=c.processing.createImportedAttempt({id:crypto.randomUUID(),taskId:published.task.id,datasetId:published.data.id,providerTaskId:'import:new-version',createdBy:'ops:test'}),versionId=crypto.randomUUID();
  assert.equal(c.processing.getActivePublishedProjectTask(published.project.id,published.task.id).attemptId,published.attempt.id);
  c.repository.upsertModelVersion({modelId:published.model.id,versionId,provider:'ltds-processing',providerModelId:published.task.id,providerVersionId:attempt.id,displayName:published.task.displayName,status:'importing',assets:[{kind:'glb',rootKey:'models',relativePath:`${published.task.id}/${attempt.id}/model.glb`,sha256:'b'.repeat(64),published:false}],makeActive:false});
  c.processing.setAttemptResult(attempt.id,published.model.id,versionId);
  c.processing.registerModelOutput({versionId,modelId:published.model.id,taskId:published.task.id,attemptId:attempt.id,projectId:published.project.id,rootKey:'models',relativePath:`${published.task.id}/${attempt.id}`,status:'staged',byteSize:1,assetCount:1});
  const operationId=crypto.randomUUID(),created=new Date().toISOString(),expires=new Date(Date.now()+60_000).toISOString(),specs=[{type:'ept',request:{optional:false}}],result={task:c.processing.getTask(published.task.id),attempt:c.processing.getAttempt(attempt.id),model:c.repository.getModelVersion(published.model.id,versionId),requiredDerivatives:specs};
  c.db.prepare("INSERT INTO dataset_operations(id,operation_type,subject,payload_json,status,lease_owner,lease_expires_at,available_at,created_at,updated_at) VALUES (?,'catalog_map','ops:test','{}','leased','import-worker',?,?,?,?)").run(operationId,expires,created,created,created);
  assert.equal(c.processing.activateImportedDerivativesForOperation(operationId,'import-worker',attempt.id,specs,result).status,'awaiting_derivatives');
  const job=c.processing.claimDerivative('failure-worker');
  assert.equal(c.processing.failDerivative(job.id,'failure-worker','new derivative failed','fault_injected',job.leaseToken),true);const terminalJournal=c.db.prepare('SELECT state,reserved_byte_size,accounted_byte_size FROM derivative_storage_journal WHERE job_id=?').get(job.id);assert.equal(terminalJournal.state,'terminal');assert.equal(terminalJournal.accounted_byte_size,0);
  const model=c.db.prepare('SELECT status,active_version_id FROM models WHERE id=?').get(published.model.id);
  assert.equal(model.status,'ready');assert.equal(model.active_version_id,published.versionId);
  assert.equal(c.processing.getModelOutput(published.versionId).status,'published');
  assert.equal(c.processing.getModelOutput(versionId).status,'failed');
  const failed=c.processing.getDatasetOperation(operationId,'ops:test');assert.equal(failed.status,'failed');assert.equal(failed.result.model.status,'ready');assert.equal(failed.result.model.activeVersion.status,'failed');assert.equal(c.processing.getActivePublishedProjectTask(published.project.id,published.task.id).attemptId,published.attempt.id);assert.equal(c.processing.listActivePublishedProjectTasksPage(published.project.id).items[0].attemptId,published.attempt.id);
  const retried=c.processing.retryDatasetOperation(operationId,'ops:test');assert.equal(retried.status,'awaiting_derivatives');const retriedJournal=c.db.prepare('SELECT state,reserved_byte_size,accounted_byte_size FROM derivative_storage_journal WHERE job_id=?').get(job.id);assert.equal(retriedJournal.state,'reserved');assert.equal(retriedJournal.accounted_byte_size,retriedJournal.reserved_byte_size);assert.equal(c.db.prepare('SELECT active_version_id FROM models WHERE id=?').get(published.model.id).active_version_id,published.versionId);assert.equal(c.processing.getModelOutput(versionId).status,'staged');
});

test('partial required retry preserves success and a different second failure stays retryable',(t)=>{
  const c=fixture(t),item=stagedImported(c,'Partial retry'),owner='import-worker',operationId=crypto.randomUUID(),created=new Date().toISOString(),expires=new Date(Date.now()+60_000).toISOString(),specs=[{type:'ept',request:{optional:false}},{type:'mesh_tiles',request:{optional:false}}],result={task:item.task,attempt:item.attempt,model:c.repository.getModelVersion(item.model.id,item.versionId),requiredDerivatives:specs};
  c.db.prepare("INSERT INTO dataset_operations(id,operation_type,subject,payload_json,status,lease_owner,lease_expires_at,available_at,created_at,updated_at) VALUES (?,'catalog_map','ops:test','{}','leased',?,?,?,?,?)").run(operationId,owner,expires,created,created,created);assert.equal(c.processing.activateImportedDerivativesForOperation(operationId,owner,item.attempt.id,specs,result).status,'awaiting_derivatives');c.processing.addModelAsset({versionId:item.versionId,kind:'pointCloud',rootKey:'datasets',relativePath:`${item.data.relativePath}/cloud.laz`,format:'laz',byteSize:1,attemptId:item.attempt.id,sha256:'d'.repeat(64)});
  c.db.prepare("UPDATE derivative_jobs SET created_at=CASE derivative_type WHEN 'ept' THEN '2026-01-01T00:00:00.000Z' ELSE '2026-01-01T00:00:01.000Z' END WHERE attempt_id=?").run(item.attempt.id);
  const first=c.processing.claimDerivative('first-failure');assert.equal(first.derivative_type,'ept');assert.equal(c.processing.failDerivative(first.id,'first-failure','first required failure','fault_one',first.lease_token),true);assert.equal(c.processing.retryDatasetOperation(operationId,'ops:test').status,'awaiting_derivatives');
  const recoveredEpt=c.processing.claimDerivative('ept-retry');assert.equal(recoveredEpt.derivative_type,'ept');const eptFiles=[{relativePath:'ept.json',byteSize:2,sha256:'a'.repeat(64)},{relativePath:'ept-data/0.bin',byteSize:3,sha256:'b'.repeat(64)}],eptAsset={versionId:item.versionId,rootKey:'models',relativePath:`${item.task.id}/${item.attempt.id}/ept-${recoveredEpt.id}/ept.json`,format:'ept',contentType:'application/json',byteSize:2,attemptId:item.attempt.id,sha256:'a'.repeat(64),manifestSha256:'c'.repeat(64),manifestFiles:eptFiles};assert.equal(c.processing.registerVerifiedEptAsset(recoveredEpt.id,'ept-retry',eptAsset,{leaseToken:recoveredEpt.lease_token}),true);assert.equal(c.processing.completeDerivativeAndMaybeReady(recoveredEpt.id,'ept-retry',{verified:true},{event:{eventId:`processing-ready-${item.attempt.id}`},leaseToken:recoveredEpt.lease_token}).ready,false);
  const second=c.processing.claimDerivative('second-failure');assert.equal(second.derivative_type,'mesh_tiles');assert.equal(c.processing.failDerivative(second.id,'second-failure','second required failure','fault_two',second.lease_token),true);assert.equal(c.processing.getDatasetOperation(operationId,'ops:test').status,'failed');assert.deepEqual(c.db.prepare("SELECT id FROM event_outbox WHERE id LIKE ? ORDER BY id").all(`processing-failed-${item.attempt.id}%`).map((row)=>row.id),[`processing-failed-${item.attempt.id}`,`processing-failed-${item.attempt.id}-retry-1`]);
  assert.equal(c.processing.retryDatasetOperation(operationId,'ops:test').status,'awaiting_derivatives');assert.equal(c.db.prepare("SELECT status FROM derivative_jobs WHERE attempt_id=? AND derivative_type='ept'").get(item.attempt.id).status,'complete');const finalJob=c.processing.claimDerivative('mesh-retry');assert.equal(finalJob.derivative_type,'mesh_tiles');const tileFiles=[{relativePath:'tileset.json',byteSize:7,sha256:'e'.repeat(64)},{relativePath:'LOD-0/leaf.b3dm',byteSize:11,sha256:'f'.repeat(64)}];c.processing.addModelAsset({versionId:item.versionId,kind:'tiles',rootKey:'models',relativePath:`${item.task.id}/${item.attempt.id}/tiles/tileset.json`,format:'3dtiles',contentType:'application/json',byteSize:7,attemptId:item.attempt.id,sha256:'e'.repeat(64),manifestSha256:'9'.repeat(64),manifestFiles:tileFiles});const final=c.processing.completeDerivativeAndMaybeReady(finalJob.id,'mesh-retry',{verified:true},{event:{eventId:`processing-ready-${item.attempt.id}`},leaseToken:finalJob.lease_token});assert.equal(final.ready,true);assert.equal(c.processing.getDatasetOperation(operationId,'ops:test').status,'succeeded');
});

test('historical attempts paginate newest-first with immutable option and provider fields',(t)=>{const c=fixture(t),project=c.processing.createProject({displayName:'History'}),data=dataset(c,project,[{name:'photo.jpg'}]),task=c.processing.createTask({projectId:project.id,datasetId:data.id,displayName:'History task'}),provider=c.processing.upsertProvider({type:'nodeodm',displayName:'ODM',endpoint:'http://127.0.0.1:3000',enabled:true});for(let i=0;i<3;i++){const attempt=c.processing.createAttempt({taskId:task.id,providerId:provider.id,options:{quality:i},capabilityFingerprint:`fp-${i}`});c.processing.transitionAttempt(attempt.id,'failed',{completedAt:new Date().toISOString()});c.db.prepare('UPDATE processing_attempts SET created_at=? WHERE id=?').run(`2026-08-17T00:00:0${i}.000Z`,attempt.id);}const first=c.processing.listAttemptsPage(task.id,{limit:2});assert.equal(first.items.length,2);assert.ok(first.nextCursor);assert.deepEqual(first.items.map((a)=>a.attemptNumber),[3,2]);assert.equal(first.items[0].options.quality,2);assert.equal(first.items[0].providerId,provider.id);const second=c.processing.listAttemptsPage(task.id,{limit:2,cursor:first.nextCursor});assert.deepEqual(second.items.map((a)=>a.attemptNumber),[1]);assert.equal(second.nextCursor,null);});

test('historical attempts API returns the frozen bounded DTO and cursor envelope',async(t)=>{const c=fixture(t),token='attempt-history-token-0000000000000000';c.processing.createAdminSession({tokenHash:auth.hashToken(token),subject:'ops:history',permissions:['viewer.processing.read'],displayUnits:'imperial',expiresAt:new Date(Date.now()+60000).toISOString()});const project=c.processing.createProject({displayName:'API history'}),data=dataset(c,project,[{name:'photo.jpg'}]),task=c.processing.createTask({projectId:project.id,datasetId:data.id,displayName:'API history task'}),provider=c.processing.upsertProvider({type:'nodeodm',displayName:'ODM',endpoint:'http://127.0.0.1:3000',enabled:true});for(let i=0;i<2;i++){const attempt=c.processing.createAttempt({taskId:task.id,providerId:provider.id,options:{quality:i},capabilityFingerprint:`api-fp-${i}`});c.processing.transitionAttempt(attempt.id,'failed',{completedAt:new Date().toISOString()});c.db.prepare('UPDATE processing_attempts SET created_at=? WHERE id=?').run(`2026-08-17T00:00:0${i}.000Z`,attempt.id);}const app=express();app.use(express.json());app.use(createProcessingApi({repository:c.repository,processing:c.processing,storage:c.storage}));const server=await new Promise((resolve)=>{const value=app.listen(0,'127.0.0.1',()=>resolve(value));});t.after(()=>new Promise((resolve)=>server.close(resolve)));const base=`http://127.0.0.1:${server.address().port}`,headers={authorization:`Bearer ${token}`},first=await fetch(`${base}/api/v1/tasks/${task.id}/attempts?limit=1`,{headers});assert.equal(first.status,200);const page=await first.json();assert.deepEqual(Object.keys(page).sort(),['attempts','nextCursor']);assert.equal(page.attempts.length,1);assert.ok(page.nextCursor);for(const key of ['id','taskId','datasetId','attemptNumber','providerId','providerTaskId','presetId','options','capabilityFingerprint','status','progress','providerOutputCursor','errorCode','errorMessage','resultModelId','resultModelVersionId','createdBy','createdAt','updatedAt','startedAt','upstreamCompletedAt','ingestedAt','completedAt','submissionPhase','uploadedFileCount'])assert.ok(Object.hasOwn(page.attempts[0],key),key);const second=await fetch(`${base}/api/v1/tasks/${task.id}/attempts?limit=1&cursor=${encodeURIComponent(page.nextCursor)}`,{headers});assert.equal(second.status,200);assert.equal((await second.json()).attempts.length,1);});

test('task draft creation is subject-durable across renewed sessions and audits once',async(t)=>{const c=fixture(t),subject='ops:draft',tokens=['draft-token-one-00000000000000000000','draft-token-two-00000000000000000000'];for(const token of tokens)c.processing.createAdminSession({tokenHash:auth.hashToken(token),subject,permissions:['viewer.processing.write','viewer.processing.read'],displayUnits:'imperial',expiresAt:new Date(Date.now()+60000).toISOString()});const project=c.processing.createProject({displayName:'Draft project'}),data=dataset(c,project,[{name:'photo.jpg'}]),app=express();app.use(express.json({verify:(req,_res,buffer)=>{req.rawBody=Buffer.from(buffer);}}));app.use(createProcessingApi({repository:c.repository,processing:c.processing,storage:c.storage}));const server=await new Promise((resolve)=>{const value=app.listen(0,'127.0.0.1',()=>resolve(value));});t.after(()=>new Promise((resolve)=>server.close(resolve)));const submissionId=crypto.randomUUID(),body={submissionId,projectId:project.id,datasetId:data.id,displayName:'Recoverable draft'},post=(token,value=body)=>fetch(`http://127.0.0.1:${server.address().port}/api/v1/tasks`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json','idempotency-key':submissionId},body:JSON.stringify(value)});const first=await post(tokens[0]);assert.equal(first.status,201);const created=await first.json();assert.equal(created.replayed,false);const replay=await post(tokens[1]);assert.equal(replay.status,200);assert.equal((await replay.json()).task.id,created.task.id);assert.equal((await post(tokens[1],{...body,displayName:'Changed'})).status,409);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='processing_task.created' AND entity_id=?").get(created.task.id).n,1);});

test('derivative terminal failure commits job, output, attempt, callback and audit together',(t)=>{const c=fixture(t),item=reviewable(c);c.processing.transitionAttempt(item.attempt.id,'derivatives');c.db.prepare("UPDATE model_outputs SET status='staged' WHERE id=?").run(item.versionId);c.db.prepare("UPDATE model_versions SET status='importing' WHERE id=?").run(item.versionId);c.processing.enqueueDerivative(item.attempt.id,'ept');const job=c.processing.claimDerivative('derivative-owner');c.db.exec("CREATE TRIGGER reject_derivative_failure_audit BEFORE INSERT ON audit_events WHEN NEW.action='processing_attempt.failed' BEGIN SELECT RAISE(ABORT,'injected derivative audit failure'); END");assert.throws(()=>c.processing.failDerivative(job.id,'derivative-owner','converter failed'),/injected derivative/);assert.equal(c.processing.getAttempt(item.attempt.id).status,'derivatives');assert.equal(c.processing.getModelOutput(item.versionId).status,'staged');assert.equal(c.db.prepare('SELECT status FROM derivative_jobs WHERE id=?').get(job.id).status,'leased');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(`processing-failed-${item.attempt.id}`).n,0);c.db.exec('DROP TRIGGER reject_derivative_failure_audit');assert.equal(c.processing.failDerivative(job.id,'derivative-owner','converter failed'),true);assert.equal(c.processing.getAttempt(item.attempt.id).status,'failed');assert.equal(c.processing.getModelOutput(item.versionId).status,'failed');assert.equal(c.db.prepare('SELECT status FROM derivative_jobs WHERE id=?').get(job.id).status,'failed');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(`processing-failed-${item.attempt.id}`).n,1);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='processing_attempt.failed' AND entity_id=?").get(item.attempt.id).n,1);});

test('ingest readiness completes its leased processing job in the same transaction',(t)=>{const c=fixture(t),item=reviewable(c),owner='ingest-owner';c.processing.transitionAttempt(item.attempt.id,'ingesting');c.db.prepare("UPDATE model_outputs SET status='staged' WHERE id=?").run(item.versionId);c.db.prepare("UPDATE model_versions SET status='importing' WHERE id=?").run(item.versionId);const job=c.processing.claimJob(owner),event={eventId:`processing-ready-${item.attempt.id}`};c.db.exec("CREATE TRIGGER reject_ingest_ready_audit BEFORE INSERT ON audit_events WHEN NEW.action='processing_attempt.ready_for_review' BEGIN SELECT RAISE(ABORT,'injected ingest ready audit failure'); END");assert.throws(()=>c.processing.completeOutputForReview(item.attempt.id,{jobId:job.id,owner,event}),/injected ingest/);assert.equal(c.db.prepare('SELECT status FROM processing_jobs WHERE id=?').get(job.id).status,'leased');assert.equal(c.processing.getAttempt(item.attempt.id).status,'ingesting');assert.equal(c.processing.getModelOutput(item.versionId).status,'staged');c.db.exec('DROP TRIGGER reject_ingest_ready_audit');assert.ok(c.processing.completeOutputForReview(item.attempt.id,{jobId:job.id,owner,event}));assert.equal(c.db.prepare('SELECT status FROM processing_jobs WHERE id=?').get(job.id).status,'complete');assert.equal(c.processing.getAttempt(item.attempt.id).status,'ready_for_review');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(event.eventId).n,1);});

test('derivative activation and ingest job completion share one visibility boundary',(t)=>{const c=fixture(t),item=reviewable(c),owner='ingest-derivative-owner';c.processing.transitionAttempt(item.attempt.id,'ingesting');c.db.prepare("UPDATE model_outputs SET status='staged' WHERE id=?").run(item.versionId);c.db.prepare("UPDATE model_versions SET status='importing' WHERE id=?").run(item.versionId);const job=c.processing.claimJob(owner),specs=[{type:'ept'},{type:'mesh_tiles',request:{quality:'balanced'}}];c.db.exec("CREATE TRIGGER reject_ingest_job_complete BEFORE UPDATE OF status ON processing_jobs WHEN NEW.status='complete' BEGIN SELECT RAISE(ABORT,'injected ingest completion failure'); END");assert.throws(()=>c.processing.completeIngestAndEnqueueDerivatives(job.id,owner,item.attempt.id,specs,{ingestedAt:new Date().toISOString()}),/injected ingest completion/);assert.equal(c.processing.getAttempt(item.attempt.id).status,'ingesting');assert.equal(c.db.prepare('SELECT status FROM processing_jobs WHERE id=?').get(job.id).status,'leased');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM derivative_jobs WHERE attempt_id=?').get(item.attempt.id).n,0);c.db.exec('DROP TRIGGER reject_ingest_job_complete');assert.ok(c.processing.completeIngestAndEnqueueDerivatives(job.id,owner,item.attempt.id,specs,{ingestedAt:new Date().toISOString()}));assert.equal(c.processing.getAttempt(item.attempt.id).status,'derivatives');assert.equal(c.db.prepare('SELECT status FROM processing_jobs WHERE id=?').get(job.id).status,'complete');assert.equal(c.db.prepare("SELECT COUNT(*) n FROM derivative_jobs WHERE attempt_id=? AND status='pending'").get(item.attempt.id).n,2);const claimed=c.processing.claimDerivative('derivative-after-commit');assert.equal(claimed.attempt_id,item.attempt.id);assert.equal(c.processing.getAttempt(item.attempt.id).status,'derivatives');});

test('final derivative completion and readiness are atomic and replayable',(t)=>{const c=fixture(t),item=reviewable(c),owner='derivative-ready-owner';c.processing.transitionAttempt(item.attempt.id,'derivatives');c.db.prepare("UPDATE model_outputs SET status='staged' WHERE id=?").run(item.versionId);c.db.prepare("UPDATE model_versions SET status='importing' WHERE id=?").run(item.versionId);c.processing.enqueueDerivative(item.attempt.id,'ept');const job=c.processing.claimDerivative(owner),event={eventId:`processing-ready-${item.attempt.id}`};c.db.exec("CREATE TRIGGER reject_derivative_ready_audit BEFORE INSERT ON audit_events WHEN NEW.action='processing_attempt.ready_for_review' BEGIN SELECT RAISE(ABORT,'injected derivative ready audit failure'); END");assert.throws(()=>c.processing.completeDerivativeAndMaybeReady(job.id,owner,{verified:true},{event}),/injected derivative ready/);assert.equal(c.db.prepare('SELECT status FROM derivative_jobs WHERE id=?').get(job.id).status,'leased');assert.equal(c.processing.getAttempt(item.attempt.id).status,'derivatives');assert.equal(c.processing.getModelOutput(item.versionId).status,'staged');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(event.eventId).n,0);c.db.exec('DROP TRIGGER reject_derivative_ready_audit');const completed=c.processing.completeDerivativeAndMaybeReady(job.id,owner,{verified:true},{event});assert.equal(completed.ready,true);assert.equal(c.db.prepare('SELECT status FROM derivative_jobs WHERE id=?').get(job.id).status,'complete');assert.equal(c.processing.getAttempt(item.attempt.id).status,'ready_for_review');assert.equal(c.processing.getModelOutput(item.versionId).status,'ready');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(event.eventId).n,1);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='processing_attempt.ready_for_review' AND entity_id=?").get(item.attempt.id).n,1);});

test('provider terminal failure rolls back and then emits exactly once',(t)=>{const c=fixture(t),item=reviewable(c),owner='provider-owner';c.db.prepare("UPDATE processing_attempts SET status='running' WHERE id=?").run(item.attempt.id);c.db.prepare("UPDATE model_outputs SET status='staged' WHERE id=?").run(item.versionId);c.db.prepare("UPDATE model_versions SET status='importing' WHERE id=?").run(item.versionId);const job=c.processing.claimJob(owner),event={eventId:`processing-failed-${item.attempt.id}`,schemaVersion:1,type:'processing.failed',projectId:item.project.id,projectDisplayName:item.project.displayName,taskId:item.task.id,taskDisplayName:item.task.displayName,attemptId:item.attempt.id,requestedBySubject:item.attempt.createdBy,status:'failed'};assert.equal(job.attempt_id,item.attempt.id);c.db.exec("CREATE TRIGGER reject_provider_failure_audit BEFORE INSERT ON audit_events WHEN NEW.action='processing_attempt.failed' BEGIN SELECT RAISE(ABORT,'injected provider audit failure'); END");assert.throws(()=>c.processing.failJobTerminal(job.id,owner,'provider_failed','upstream failed',event),/injected provider/);assert.equal(c.db.prepare('SELECT status FROM processing_jobs WHERE id=?').get(job.id).status,'leased');assert.equal(c.processing.getAttempt(item.attempt.id).status,'running');assert.equal(c.processing.getModelOutput(item.versionId).status,'staged');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(event.eventId).n,0);c.db.exec('DROP TRIGGER reject_provider_failure_audit');assert.ok(c.processing.failJobTerminal(job.id,owner,'provider_failed','upstream failed',event));assert.equal(c.db.prepare('SELECT status FROM processing_jobs WHERE id=?').get(job.id).status,'failed');assert.equal(c.processing.getAttempt(item.attempt.id).status,'failed');assert.equal(c.processing.getModelOutput(item.versionId).status,'failed');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(event.eventId).n,1);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='processing_attempt.failed' AND entity_id=?").get(item.attempt.id).n,1);});

test('administrative entity and metadata lifecycle audits own their transactions',(t)=>{const c=fixture(t),project=c.processing.createProject({displayName:'Original project'}),data=dataset(c,project,[{name:'photo.jpg'}]),task=c.processing.createTask({projectId:project.id,datasetId:data.id,displayName:'Original task'}),cases=[{action:'project.updated',entity:'project',read:()=>c.processing.getProject(project.id).displayName,mutate:()=>c.processing.auditedMutation({actorId:'ops:test',action:'project.updated',entityType:'project',entityId:project.id},()=>c.processing.updateProject(project.id,{displayName:'Changed project'}))},{action:'dataset.updated',entity:'dataset',read:()=>c.processing.getDataset(data.id).displayName,mutate:()=>c.processing.auditedMutation({actorId:'ops:test',action:'dataset.updated',entityType:'dataset',entityId:data.id},()=>c.processing.updateDatasetMetadata(data.id,{displayName:'Changed dataset'}))},{action:'processing_task.updated',entity:'task',read:()=>c.processing.getTask(task.id).displayName,mutate:()=>c.processing.auditedMutation({actorId:'ops:test',action:'processing_task.updated',entityType:'processing_task',entityId:task.id},()=>c.processing.updateTaskMetadata(task.id,{displayName:'Changed task'}))}];for(const [index,item] of cases.entries()){const before=item.read(),trigger=`reject_entity_audit_${index}`;c.db.exec(`CREATE TRIGGER ${trigger} BEFORE INSERT ON audit_events WHEN NEW.action='${item.action}' BEGIN SELECT RAISE(ABORT,'injected ${item.entity} audit failure'); END`);assert.throws(item.mutate,/injected/);assert.equal(item.read(),before);c.db.exec(`DROP TRIGGER ${trigger}`);assert.ok(item.mutate());assert.equal(c.db.prepare('SELECT COUNT(*) n FROM audit_events WHERE action=?').get(item.action).n,1);}const output=reviewable(c);c.db.prepare("UPDATE model_outputs SET storage_mode='external_reference' WHERE id=?").run(output.versionId);assert.ok(c.processing.archiveModelOutput(output.versionId,'ops:test'));c.db.exec("CREATE TRIGGER reject_output_trash_audit BEFORE INSERT ON audit_events WHEN NEW.action='output.trashed' BEGIN SELECT RAISE(ABORT,'injected output audit failure'); END");assert.throws(()=>c.processing.trashMetadataOutput(output.versionId,'ops:test'),/injected output/);assert.equal(c.processing.getModelOutput(output.versionId).status,'archived');assert.equal(c.db.prepare("SELECT COUNT(*) n FROM storage_trash WHERE entity_type='output' AND entity_id=?").get(output.versionId).n,0);c.db.exec('DROP TRIGGER reject_output_trash_audit');assert.ok(c.processing.trashMetadataOutput(output.versionId,'ops:test'));assert.equal(c.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='output.trashed' AND entity_id=?").get(output.versionId).n,1);});

test('provider preset catalog and review mutations roll back with their audits',(t)=>{const c=fixture(t),reject=(name,action)=>c.db.exec(`CREATE TRIGGER ${name} BEFORE INSERT ON audit_events WHEN NEW.action='${action}' BEGIN SELECT RAISE(ABORT,'injected ${action} audit failure'); END`);reject('reject_provider_created','provider.created');assert.throws(()=>c.processing.upsertProvider({id:'provider-atomic',type:'nodeodm',displayName:'Atomic provider',endpoint:'http://127.0.0.1:3000'},{actorId:'ops:test',action:'provider.created',entityType:'processing_provider'}),/injected provider.created/);assert.equal(c.processing.getProvider('provider-atomic')==null,true);c.db.exec('DROP TRIGGER reject_provider_created');reject('reject_preset_created','processing_preset.created');assert.throws(()=>c.processing.createPreset({id:'preset-atomic',displayName:'Atomic preset'},{actorId:'ops:test',action:'processing_preset.created',entityType:'processing_preset'}),/injected processing_preset.created/);assert.equal(c.processing.getPreset('preset-atomic')==null,true);c.db.exec('DROP TRIGGER reject_preset_created');reject('reject_catalog_scan','catalog_import.scan_queued');assert.throws(()=>c.processing.createCatalogScanOperation({provider:'webodm',subject:'ops:test',sessionId:'session',audit:{actorId:'ops:test',action:'catalog_import.scan_queued',entityType:'dataset_operation'}}),/injected catalog_import.scan_queued/);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM dataset_operations').get().n,0);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM catalog_import_scans').get().n,0);c.db.exec('DROP TRIGGER reject_catalog_scan');const item=reviewable(c),expiresAt=new Date(Date.now()+60000).toISOString(),grantInput={modelId:item.model.id,modelVersionId:item.versionId,reviewAttemptId:item.attempt.id,sessionMode:'review',subject:'ops:test',audience:'ops',permissions:{view:true},expiresAt};reject('reject_review_created','processing_review_session.created');assert.throws(()=>c.repository.createSessionGrantAudited(grantInput,{actorType:'admin',actorId:'ops:test',action:'processing_review_session.created',entityType:'processing_attempt'}),/injected processing_review_session.created/);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM session_grants WHERE review_attempt_id=?').get(item.attempt.id).n,0);c.db.exec('DROP TRIGGER reject_review_created');const grant=c.repository.createSessionGrantAudited(grantInput,{actorType:'admin',actorId:'ops:test',action:'processing_review_session.created',entityType:'processing_attempt'});assert.ok(grant.id);reject('reject_review_revoked','processing_review_session.revoked');assert.throws(()=>c.repository.revokeReviewSessions({attemptId:item.attempt.id,subject:'ops:test',audit:{actorType:'admin',actorId:'ops:test',action:'processing_review_session.revoked',entityType:'processing_attempt'}}),/injected processing_review_session.revoked/);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM session_grants WHERE id=?').get(grant.id).n,1);});

test('capability probe state and its redacted audit commit together',(t)=>{const c=fixture(t),provider=c.processing.upsertProvider({type:'nodeodm',displayName:'Probe audit',endpoint:'http://127.0.0.1:3000',enabled:false});c.processing.updateProviderCapabilities(provider.id,{capabilities:{options:[]},fingerprint:'a'.repeat(64),health:'healthy'});c.db.exec("CREATE TRIGGER reject_capability_probe_audit BEFORE INSERT ON audit_events WHEN NEW.action='provider.capabilities_probed' BEGIN SELECT RAISE(ABORT,'injected probe audit failure'); END");assert.throws(()=>c.processing.updateProviderCapabilities(provider.id,{capabilities:{options:[],credential:'never-audit-me',sourcePath:'/mnt/private/provider'},fingerprint:'b'.repeat(64),health:'healthy'},{auditActorId:'ops:test'}),/injected probe/);assert.equal(c.processing.getProvider(provider.id).capabilityFingerprint,'a'.repeat(64));c.db.exec('DROP TRIGGER reject_capability_probe_audit');assert.ok(c.processing.updateProviderCapabilities(provider.id,{capabilities:{options:[],credential:'never-audit-me',sourcePath:'/mnt/private/provider'},fingerprint:'b'.repeat(64),health:'healthy'},{auditActorId:'ops:test'}));const row=c.db.prepare("SELECT details_json FROM audit_events WHERE action='provider.capabilities_probed' AND entity_id=?").get(provider.id);assert.deepEqual(JSON.parse(row.details_json),{health:'healthy',capabilityFingerprint:'b'.repeat(64)});assert.doesNotMatch(row.details_json,/never-audit-me|\/mnt\/private/);});

test('import preview enqueue cancel and retry own bounded audits and preserve receipts on rollback',(t)=>{const c=fixture(t),subject='ops:imports',route='/api/v1/dataset-imports/preview',makeReceipt=(key)=>{const value={subject,key,method:'POST',path:route,requestHash:crypto.createHash('sha256').update(key).digest('hex')};assert.equal(c.processing.reserveSubjectOperationReceipt(value).created,true);return value;},secretPath='customer/private/token-never-audit';const receipt=makeReceipt('preview-enqueue');c.db.exec("CREATE TRIGGER reject_preview_enqueue_audit BEFORE INSERT ON audit_events WHEN NEW.action='dataset_operation.import_preview_enqueued' BEGIN SELECT RAISE(ABORT,'injected preview enqueue audit failure'); END");assert.throws(()=>c.processing.createImportPreviewOperation({request:{rootKey:'dataset_import',relativePath:secretPath},subject,sessionId:'session-secret',receipt,auditActorId:subject}),/injected preview enqueue/);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM dataset_operations').get().n,0);assert.equal(c.processing.getSubjectOperationReceipt(subject,receipt.key).operationId,null);c.db.exec('DROP TRIGGER reject_preview_enqueue_audit');const operation=c.processing.createImportPreviewOperation({request:{rootKey:'dataset_import',relativePath:secretPath},subject,sessionId:'session-secret',receipt,auditActorId:subject});assert.equal(c.processing.getSubjectOperationReceipt(subject,receipt.key).operationId,operation.id);let audit=c.db.prepare("SELECT details_json FROM audit_events WHERE action='dataset_operation.import_preview_enqueued' AND entity_id=?").get(operation.id);assert.deepEqual(JSON.parse(audit.details_json),{operationType:'import_preview'});assert.doesNotMatch(audit.details_json,/customer|token-never-audit|session-secret/);c.db.exec("CREATE TRIGGER reject_operation_cancel_audit BEFORE INSERT ON audit_events WHEN NEW.action='dataset_operation.cancelled' BEGIN SELECT RAISE(ABORT,'injected cancel audit failure'); END");assert.throws(()=>c.processing.cancelImportPreviewOperation(operation.id,subject,subject),/injected cancel/);assert.equal(c.processing.getDatasetOperation(operation.id,subject).status,'queued');c.db.exec('DROP TRIGGER reject_operation_cancel_audit');assert.equal(c.processing.cancelImportPreviewOperation(operation.id,subject,subject).status,'cancelled');const retryable=c.processing.createImportPreviewOperation({request:{rootKey:'dataset_import',relativePath:'retry-private-path'},subject,sessionId:null}),claim=c.processing.claimDatasetOperation('retry-worker');assert.equal(claim.id,retryable.id);assert.equal(c.processing.failDatasetOperation(retryable.id,'retry-worker','upstream_failed','token=secret /mnt/private'),true);c.db.exec("CREATE TRIGGER reject_operation_retry_audit BEFORE INSERT ON audit_events WHEN NEW.action='dataset_operation.retry_requested' BEGIN SELECT RAISE(ABORT,'injected retry audit failure'); END");assert.throws(()=>c.processing.retryDatasetOperation(retryable.id,subject,subject),/injected retry/);assert.equal(c.processing.getDatasetOperation(retryable.id,subject).status,'failed');c.db.exec('DROP TRIGGER reject_operation_retry_audit');assert.equal(c.processing.retryDatasetOperation(retryable.id,subject,subject).status,'queued');audit=c.db.prepare("SELECT details_json FROM audit_events WHERE action='dataset_operation.retry_requested' AND entity_id=?").get(retryable.id);assert.deepEqual(JSON.parse(audit.details_json),{operationType:'import_preview'});assert.doesNotMatch(audit.details_json,/secret|private|upstream/);});

test('upload finalization enqueue rolls back upload and receipt when audit insertion fails',(t)=>{const c=fixture(t),subject='ops:upload',project=c.processing.createProject({displayName:'Upload audit'}),draft=c.processing.createDataset({projectId:project.id,displayName:'Private path dataset',storageMode:'managed',rootKey:'datasets',relativePath:'private/customer/path'}),created=c.processing.createUpload({datasetId:draft.id,files:[{id:'f',relativePath:'secret-name.jpg',byteSize:0,sha256:crypto.createHash('sha256').digest('hex')}],subject,chunkSize:8,expiresAt:new Date(Date.now()+60000).toISOString()}),receipt={subject,key:'upload-finalize',method:'POST',path:`/api/v1/admin/uploads/${created.upload.id}/finalize`,requestHash:'c'.repeat(64)};c.processing.reserveSubjectOperationReceipt(receipt);c.db.exec("CREATE TRIGGER reject_upload_finalize_audit BEFORE INSERT ON audit_events WHEN NEW.action='dataset_operation.upload_finalize_enqueued' BEGIN SELECT RAISE(ABORT,'injected upload finalize audit failure'); END");assert.throws(()=>c.processing.createUploadFinalizeOperation(created.upload.id,subject,receipt,subject),/injected upload finalize/);assert.equal(c.processing.getUpload(created.upload.id).status,'open');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM dataset_operations WHERE upload_id=?').get(created.upload.id).n,0);assert.equal(c.processing.getSubjectOperationReceipt(subject,receipt.key).operationId,null);c.db.exec('DROP TRIGGER reject_upload_finalize_audit');const operation=c.processing.createUploadFinalizeOperation(created.upload.id,subject,receipt,subject),row=c.db.prepare("SELECT details_json FROM audit_events WHERE action='dataset_operation.upload_finalize_enqueued' AND entity_id=?").get(operation.id);assert.equal(c.processing.getUpload(created.upload.id).status,'finalizing');assert.deepEqual(JSON.parse(row.details_json),{operationType:'upload_finalize',datasetId:draft.id,uploadId:created.upload.id});assert.doesNotMatch(row.details_json,/secret-name|private\/customer/);});

test('import adoption claim provisional dataset operation receipt and audit share one transaction',(t)=>{const c=fixture(t),subject='ops:adopt',project=c.processing.createProject({displayName:'Adopt audit'}),previewOperation=c.processing.createImportPreviewOperation({request:{rootKey:'dataset_import',relativePath:'private/source/tree'},subject,sessionId:'session-adopt'}),claim=c.processing.claimDatasetOperation('preview-worker'),preview={treeFingerprint:'d'.repeat(64),files:[]},completed=c.processing.completeImportPreviewOperation(previewOperation.id,'preview-worker',{request:{rootKey:'dataset_import',relativePath:'private/source/tree'},preview,publicPreview:{treeFingerprint:preview.treeFingerprint,fileCount:0,byteSize:0}});assert.equal(claim.id,previewOperation.id);const receipt={subject,key:'adopt-operation',method:'POST',path:'/api/v1/dataset-imports/adopt',requestHash:'e'.repeat(64)};c.processing.reserveSubjectOperationReceipt(receipt);c.db.exec("CREATE TRIGGER reject_import_adopt_audit BEFORE INSERT ON audit_events WHEN NEW.action='dataset_operation.import_adopt_enqueued' BEGIN SELECT RAISE(ABORT,'injected import adopt audit failure'); END");assert.throws(()=>c.processing.createImportAdoptOperation({previewToken:completed.result.previewToken,sessionId:'session-adopt',subject,projectId:project.id,displayName:'Secret customer name',storageMode:'adopted',receipt,auditActorId:subject}),/injected import adopt/);assert.equal(c.db.prepare("SELECT claimed_at FROM dataset_import_previews WHERE id=?").get(completed.result.id).claimed_at,null);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM datasets WHERE project_id=? AND status='finalizing'").get(project.id).n,0);assert.equal(c.processing.getSubjectOperationReceipt(subject,receipt.key).operationId,null);c.db.exec('DROP TRIGGER reject_import_adopt_audit');const operation=c.processing.createImportAdoptOperation({previewToken:completed.result.previewToken,sessionId:'session-adopt',subject,projectId:project.id,displayName:'Secret customer name',storageMode:'adopted',receipt,auditActorId:subject}),row=c.db.prepare("SELECT details_json FROM audit_events WHERE action='dataset_operation.import_adopt_enqueued' AND entity_id=?").get(operation.id);assert.deepEqual(JSON.parse(row.details_json),{operationType:'import_adopt',datasetId:operation.datasetId,storageMode:'adopted'});assert.doesNotMatch(row.details_json,/Secret customer|private\/source|previewToken|session-adopt/);});

test('external catalog bytes are counted once through metadata trash restore and purge',(t)=>{const c=fixture(t),item=reviewable(c),bytes=item.data.byteSize;c.db.prepare("UPDATE model_outputs SET storage_mode='external_reference',root_key=?,relative_path=?,byte_size=? WHERE id=?").run(`webodm@${item.versionId}`,'project/task',bytes,item.versionId);assert.equal(c.processing.projectStorage(item.project.id).project.datasetBytes,0);assert.equal(c.processing.projectStorage(item.project.id).project.outputBytes,bytes);assert.equal(c.processing.taskStorage(item.task.id).task.totalBytes,bytes);assert.equal(c.processing.archiveModelOutput(item.versionId).status,'archived');assert.notEqual(c.processing.getTask(item.task.id).status,'archived');const trashed=c.processing.trashMetadataOutput(item.versionId,'ops:test');assert.ok(trashed);assert.equal(c.processing.projectStorage(item.project.id).project.datasetBytes,bytes);assert.equal(c.processing.projectStorage(item.project.id).project.outputBytes,0);assert.equal(c.processing.restoreMetadataOutput(trashed.id).status,'archived');assert.equal(c.processing.projectStorage(item.project.id).project.totalBytes,bytes);const again=c.processing.trashMetadataOutput(item.versionId,'ops:test');assert.ok(c.processing.purgeMetadataOutput(again.id).permanentlyDeletedAt);assert.equal(c.processing.getModelOutput(item.versionId).byteSize,0);assert.equal(c.processing.projectStorage(item.project.id).project.datasetBytes,bytes);});

test('historical output archive preserves task and active archive permits a new attempt',(t)=>{const c=fixture(t),historical=reviewable(c);c.processing.transitionAttempt(historical.attempt.id,'published');const replacement=c.processing.createAttempt({taskId:historical.task.id,providerId:historical.attempt.providerId,options:{generation:2}});assert.equal(c.processing.archiveModelOutput(historical.versionId).status,'archived');assert.equal(c.processing.getTask(historical.task.id).activeAttemptId,replacement.id);assert.notEqual(c.processing.getTask(historical.task.id).status,'archived');c.processing.cancelAttempt(replacement.id,'ops:test');const active=reviewable(c);assert.ok(c.processing.publishAttemptAtomic(active.attempt.id,['glb'],{actorId:'ops:test'}));assert.equal(c.processing.archiveModelOutput(active.versionId).status,'archived');assert.equal(c.processing.getTask(active.task.id).activeAttemptId,null);assert.equal(c.processing.getTask(active.task.id).status,'draft');const next=c.processing.createAttempt({taskId:active.task.id,providerId:active.attempt.providerId,options:{generation:2}});assert.equal(next.attemptNumber,2);});

test('cancelling a staged attempt invalidates its unpublished output and review capabilities',(t)=>{const c=fixture(t),item=reviewable(c);c.processing.transitionAttempt(item.attempt.id,'derivatives');c.db.prepare("UPDATE model_outputs SET status='staged' WHERE id=?").run(item.versionId);c.db.prepare("UPDATE model_versions SET status='importing' WHERE id=?").run(item.versionId);const t0=new Date(Date.now()+60000).toISOString();c.db.prepare("INSERT INTO session_grants(id,model_id,subject,audience,permissions_json,expires_at,created_at,session_mode,model_version_id,review_attempt_id) VALUES (?,?,?,?,?,?,?,?,?,?)").run(crypto.randomUUID(),item.model.id,'ops:test','ops','{}',t0,new Date().toISOString(),'review',item.versionId,item.attempt.id);const cancelled=c.processing.cancelAttempt(item.attempt.id,'ops:test');assert.equal(cancelled.status,'cancelled');assert.equal(c.processing.getModelOutput(item.versionId).status,'failed');assert.equal(c.db.prepare('SELECT status FROM model_versions WHERE id=?').get(item.versionId).status,'failed');assert.equal(c.db.prepare("SELECT COUNT(*) n FROM session_grants WHERE review_attempt_id=?").get(item.attempt.id).n,0);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='processing_attempt.cancelled' AND entity_id=?").get(item.attempt.id).n,1);});

test('synthetic high-file-count filesystem finalization indexes and accounts real bytes with admission checks',(t)=>{const c=fixture(t),project=c.processing.createProject({displayName:'Scale CI'}),relativePath=crypto.randomUUID(),draft=c.processing.createDataset({projectId:project.id,displayName:'Synthetic 2500',storageMode:'managed',rootKey:'datasets',relativePath}),directory=path.join(c.root,'datasets',relativePath),files=[];fs.mkdirSync(directory,{recursive:true});for(let i=0;i<2500;i++){const name=`flight/${String(i).padStart(5,'0')}.jpg`,absolute=path.join(directory,name),body=Buffer.alloc(1024,i%251);fs.mkdirSync(path.dirname(absolute),{recursive:true});fs.writeFileSync(absolute,body);files.push({relativePath:name,byteSize:body.length,sha256:crypto.createHash('sha256').update(body).digest('hex')});}const large=path.join(directory,'administrative.bin'),chunk=Buffer.alloc(1024*1024,7),hash=crypto.createHash('sha256'),handle=fs.openSync(large,'w');try{for(let i=0;i<8;i++){fs.writeSync(handle,chunk);hash.update(chunk);}}finally{fs.closeSync(handle);}files.push({relativePath:'administrative.bin',byteSize:8*1024*1024,sha256:hash.digest('hex')});const finalized=c.processing.finalizeDataset(draft.id,files,crypto.createHash('sha256').update(JSON.stringify(files)).digest('hex'));assert.equal(finalized.fileCount,2501);assert.equal(finalized.byteSize,2500*1024+8*1024*1024);assert.equal(c.processing.projectStorage(project.id).project.datasetBytes,finalized.byteSize);assert.equal(c.storage.requireProcessingHeadroom(finalized.byteSize,[]).models.ok,true);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM dataset_files WHERE dataset_id=? AND processing_role='image'").get(draft.id).n,2500);});

test('bounded upload streams assemble into finalization and admission retries after backpressure',async(t)=>{const c=fixture(t),warnings=[],warning=(value)=>{if(value.name==='MaxListenersExceededWarning'&&/WriteStream/.test(value.message))warnings.push(value);};process.on('warning',warning);t.after(()=>process.removeListener('warning',warning));const project=c.processing.createProject({displayName:'Stream scale'}),relativePath=crypto.randomUUID(),draft=c.processing.createDataset({projectId:project.id,displayName:'Stream dataset',storageMode:'managed',rootKey:'datasets',relativePath}),chunkSize=64*1024,specs=[];for(let i=0;i<64;i++){const body=Buffer.alloc(64*1024,i),id=`image-${i}`,relativePath=`stream/${String(i).padStart(4,'0')}.jpg`;specs.push({id,relativePath,byteSize:body.length,sha256:crypto.createHash('sha256').update(body).digest('hex'),processingRole:'image',body});}const largeBody=Buffer.alloc(2*1024*1024,9);specs.push({id:'large-admin',relativePath:'stream/large.bin',byteSize:largeBody.length,sha256:crypto.createHash('sha256').update(largeBody).digest('hex'),processingRole:'administrative',body:largeBody});const manifest=specs.map(({body,...spec})=>spec),created=c.processing.createUpload({datasetId:draft.id,files:manifest,subject:'ops:scale',chunkSize,expiresAt:new Date(Date.now()+60000).toISOString()}),upload=created.upload;for(const spec of specs){for(let index=0,offset=0;offset<spec.body.length;index++,offset+=chunkSize){const bytes=spec.body.subarray(offset,Math.min(spec.body.length,offset+chunkSize)),sha256=crypto.createHash('sha256').update(bytes).digest('hex'),written=c.storage.writeChunk(upload.id,spec.id,index,bytes,sha256);c.processing.recordChunk({uploadId:upload.id,fileId:spec.id,chunkIndex:index,relativePath:spec.relativePath,...written});}}const assembled=[];for(const spec of manifest)assembled.push(await c.storage.assembleFile(upload,spec,c.processing.listChunks(upload.id,spec.id),draft.relativePath));await new Promise((resolve)=>setImmediate(resolve));assert.deepEqual(warnings,[]);const finalized=c.processing.finalizeDataset(draft.id,assembled,crypto.createHash('sha256').update(JSON.stringify(assembled)).digest('hex'));assert.equal(finalized.fileCount,65);assert.equal(finalized.byteSize,64*64*1024+2*1024*1024);const blocked=new StorageManager({...c.storage.config,storageReserveBytes:Number.MAX_SAFE_INTEGER});blocked.initialize();assert.throws(()=>blocked.requireProcessingHeadroom(finalized.byteSize,[]),{code:'insufficient_storage'});assert.equal(c.storage.requireProcessingHeadroom(finalized.byteSize,[]).models.ok,true);assert.equal(c.processing.projectStorage(project.id).project.totalBytes,finalized.byteSize);});

test('v15 upgrade reconciles legacy failed and in-progress unpublished outputs',(t)=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'ltds-v15-upgrade-')),file=path.join(root,'viewer.sqlite'),db=new DatabaseSync(file);db.exec('PRAGMA foreign_keys=ON; CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,name TEXT NOT NULL,applied_at TEXT NOT NULL)');for(const migration of MIGRATIONS.filter((item)=>item.version<=15)){db.exec('BEGIN IMMEDIATE');try{db.exec(migration.sql);db.prepare('INSERT INTO schema_migrations(version,name,applied_at) VALUES (?,?,?)').run(migration.version,migration.name,new Date().toISOString());db.exec('COMMIT');}catch(error){db.exec('ROLLBACK');throw error;}}const processing=new ProcessingRepository(db),repository=new ViewerRepository(db),project=processing.createProject({displayName:'Upgrade'}),data=processing.createDataset({projectId:project.id,displayName:'Legacy',storageMode:'managed',rootKey:'datasets',relativePath:crypto.randomUUID()});db.prepare("UPDATE datasets SET status='finalized',manifest_sha256=?,finalized_at=? WHERE id=?").run('a'.repeat(64),new Date().toISOString(),data.id);const task=processing.createTask({projectId:project.id,datasetId:data.id,displayName:'Legacy task'}),provider=processing.upsertProvider({type:'nodeodm',displayName:'ODM',endpoint:'http://127.0.0.1:3000',enabled:true}),make=(status)=>{const attempt=processing.createAttempt({taskId:task.id,providerId:provider.id,options:{}}),model=repository.upsertModelVersion({provider:'ltds-processing',providerModelId:task.id,providerVersionId:attempt.id,displayName:'Legacy',status:'ready',assets:[{kind:'glb',rootKey:'models',relativePath:`${task.id}/${attempt.id}/model.glb`,sha256:'b'.repeat(64),published:false}],makeActive:false}),versionId=db.prepare('SELECT id FROM model_versions WHERE model_id=? AND provider_version_id=?').get(model.id,attempt.id).id;processing.setAttemptResult(attempt.id,model.id,versionId);const outputTime=new Date().toISOString();db.prepare("INSERT INTO model_outputs(id,model_id,task_id,attempt_id,project_id,root_key,relative_path,storage_mode,status,byte_size,asset_count,created_at,updated_at) VALUES (?,?,?,?,?,'models',?,'managed','ready',1,1,?,?)").run(versionId,model.id,task.id,attempt.id,project.id,`${task.id}/${attempt.id}`,outputTime,outputTime);processing.transitionAttempt(attempt.id,status,{completedAt:status==='failed'?new Date().toISOString():null});return{attempt,versionId};},failed=make('failed'),staged=make('derivatives');applyMigrations(db);assert.equal(processing.getModelOutput(failed.versionId).status,'failed');assert.equal(db.prepare('SELECT status FROM model_versions WHERE id=?').get(failed.versionId).status,'failed');assert.equal(processing.getModelOutput(staged.versionId).status,'staged');assert.equal(db.prepare('SELECT status FROM model_versions WHERE id=?').get(staged.versionId).status,'importing');db.close();fs.rmSync(root,{recursive:true,force:true});t.after(()=>{});});
